<template>
  <div class="card-wrapper" v-for="item in sortedList" :key="item.player.id">
    <div class="song-card" :style="{ background: mainColor }" @click="goToLink(item.player)">
      <div class="rank-box">
        <span class="rank-text">#{{ item.player.rank }}</span>
      </div>

      <div class="song-info">
        <h2 class="song-name" :style="{ color: textColor }">{{ item.player.name }}</h2>
        <p class="song-id" :style="{ color: textColor }">@{{ item.player.id }}</p>
      </div>

      <div class="right-group">
        <div class="song-score" :style="{ color: textColor }">
          {{ Number(item.player.score).toFixed(4) }}
        </div>
      </div>

      <div class="charts-container">
        <div class="charts-list">
          <template v-for="(chart, idx) in item.charts" :key="idx">
            <div 
              class="chart-item" 
              v-if="chart && chart.level != null && chart.level !== 0"
            >
              <div class="chart-left" :style="{ color: textColor }">
                <span class="chart-name">{{ chart.name }}</span>
                <span class="chart-level">Lv.{{ Number(chart.level).toFixed(1) }}</span>
              </div>

              <div class="chart-right" :style="{ color: textColor }">
                <span class="chart-score">{{ chart.score }}</span>
                <span class="chart-value">{{ Number(chart.value).toFixed(4) }}</span>
              </div>
            </div>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'

const props = defineProps({
  songList: { type: Object, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

const sortedList = computed(() => {
  return Object.values(props.songList).sort((a, b) => a.player.rank - b.player.rank)
})

const goToLink = (player) => {
  if (player.bvid) window.open(`https://www.bilibili.com/video/${player.bvid}`, '_blank')
}
</script>

<style scoped>
.card-wrapper {
  width: 100%;
  margin-bottom: 0.12rem;
}

.song-card {
  width: 100%;
  min-height: 1.2rem;
  display: flex;
  position: relative;
  padding: 0 0.24rem 0.2rem 0;
  box-shadow: 0 0.02rem 0.1rem rgba(0, 0, 0, 0.2);
  cursor: pointer;
  overflow: hidden;
  flex-direction: column;
}

.rank-box {
  width: 1rem;
  height: 100%;
  position: absolute;
  left: 0;
  top: 0;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  z-index: 1;
}

.rank-text {
  font-size: 0.35rem;
  font-weight: bold;
  color: #000;
}

.song-info {
  width: calc(100% - 1rem);
  margin-left: 1.1rem;
  padding: 0.24rem 0 0.16rem 0.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.06rem;
  z-index: 2;
  position: relative;
}

.song-name {
  font-size: 0.28rem;
  font-weight: 600;
  margin: 0;
  max-width: 4rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.song-id {
  font-size: 0.16rem;
  margin: 0;
  opacity: 0.8;
}

.right-group {
  position: absolute;
  right: 0.24rem;
  top: 0.4rem;
  z-index: 2;
}

.song-score {
  font-size: 0.32rem;
  font-weight: 800;
}

.charts-container {
  width: calc(100% - 1.3rem);
  margin-left: 1.2rem;
  z-index: 2;
  position: relative;
}

.charts-list {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
}

.chart-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.17rem;
  width: 100%;
}

.chart-left {
  display: flex;
  align-items: center;
  gap: 0.16rem;
  flex: 1;
}

.chart-name {
  font-weight: 500;
}

.chart-level {
  white-space: nowrap;
}

.chart-right {
  display: flex;
  align-items: center;
  gap: 0.2rem;
  justify-content: flex-end;
  min-width: 1.8rem;
}

.chart-value {
  font-weight: bold;
  white-space: nowrap;
}

.chart-score {
  white-space: nowrap;
}
</style>